def evaluator_optimizer(brief: str, max_rounds: int = 3) -> str:
    draft = generate_initial(brief)
    for round_n in range(max_rounds):
        critique = evaluate(draft, brief)
        if critique["approved"]:
            return draft
        draft = generate_revision(draft, critique["feedback"])
    return draft  # devuelve el último, incluso si no aprobado

def generate_initial(brief: str) -> str:
    return client.messages.create(
        model="claude-sonnet-4-6", max_tokens=600,
        system="Eres un copywriter senior. Escribe el email solicitado.",
        messages=[{"role": "user", "content": brief}]
    ).content[0].text

def evaluate(draft: str, brief: str) -> dict:
    resp = client.messages.create(
        model="claude-sonnet-4-6", max_tokens=400,
        system=(
            "Eres editor crítico. Evalúa si el draft cumple el brief. "
            "Devuelve JSON: {approved: bool, feedback: 'qué mejorar'}"
        ),
        messages=[{"role": "user", "content": f"BRIEF:\n{brief}\n\nDRAFT:\n{draft}"}]
    )
    import json
    return json.loads(resp.content[0].text)

def generate_revision(draft: str, feedback: str) -> str:
    return client.messages.create(
        model="claude-sonnet-4-6", max_tokens=600,
        messages=[{"role": "user",
                   "content": f"Revisa este draft según el feedback:\n\nDRAFT:\n{draft}\n\nFEEDBACK:\n{feedback}"}]
    ).content[0].text

import psycopg
from anthropic import Anthropic

client = Anthropic()
conn = psycopg.connect("postgresql://...")

SEARCH_TOOL = {
    "name": "search_knowledge",
    "description": (
        "Busca en la base de conocimiento semántica. "
        "Devuelve top 5 fragmentos relevantes. "
        "Úsala iterativamente: si el primer resultado no resuelve, refina la query."
    ),
    "input_schema": {
        "type": "object",
        "properties": {
            "query": {"type": "string", "description": "Búsqueda en lenguaje natural"},
            "collection": {"type": "string", "enum": ["docs", "incidents", "runbooks"]}
        },
        "required": ["query"]
    }
}

def search_knowledge(query: str, collection: str = "docs", tenant_id: str = None):
    embedding = embed(query)  # OpenAI ada-002 o voyage-3
    rows = conn.execute(
        "SELECT content, source, 1 - (embedding <=> %s) AS score "
        "FROM knowledge WHERE collection = %s AND tenant_id = %s "
        "ORDER BY embedding <=> %s LIMIT 5",
        (embedding, collection, tenant_id, embedding)
    ).fetchall()
    return [{"content": r[0], "source": r[1], "score": r[2]} for r in rows]

-- Habilitar pgvector
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE knowledge (
  id           BIGSERIAL PRIMARY KEY,
  tenant_id    UUID NOT NULL,
  collection   TEXT NOT NULL,
  content      TEXT NOT NULL,
  source       TEXT,
  embedding    VECTOR(1536) NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  decay_until  TIMESTAMPTZ  -- política de retención: NULL = forever
);

CREATE INDEX idx_knowledge_tenant ON knowledge(tenant_id);
CREATE INDEX idx_knowledge_embedding ON knowledge
  USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);

-- Row-Level Security: defense in depth
ALTER TABLE knowledge ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON knowledge
  USING (tenant_id = current_setting('app.tenant_id')::uuid);

-- En cada request, setea el tenant_id ANTES de queries:
-- SET LOCAL app.tenant_id = 'uuid-del-tenant';

ACTIONS_REQUIRING_APPROVAL = {
    "delete_data", "modify_billing", "change_dns",
    "rollback_production", "scale_to_zero"
}
SAFE_ACTIONS = {
    "restart_service", "clear_cache", "increase_replicas"
}

def execute_remediation(plan: dict, tenant_id: str) -> dict:
    action = plan["action"]
    impact = plan["estimated_impact"]

    # 1. Whitelist check
    if action not in (SAFE_ACTIONS | ACTIONS_REQUIRING_APPROVAL):
        return {"success": False, "reason": "action not allowed"}

    # 2. Dry-run
    simulation = simulate_action(action, plan["params"], tenant_id)
    if simulation["users_affected"] > 100:
        return {"success": False, "reason": "impact too high",
                "requires": "human_approval"}

    # 3. Human gate para acciones críticas
    if action in ACTIONS_REQUIRING_APPROVAL:
        approval = request_human_approval(plan)
        if not approval["approved"]:
            return {"success": False, "reason": "human rejected"}

    # 4. Ejecuta de verdad
    result = execute(action, plan["params"])
    return {"success": True, "result": result, "audit_id": log_action(plan)}

-- 1. Tabla con tenant_id
CREATE TABLE incidents (
  id          BIGSERIAL PRIMARY KEY,
  tenant_id   UUID NOT NULL,
  title       TEXT NOT NULL,
  severity    TEXT NOT NULL,
  status      TEXT NOT NULL DEFAULT 'open',
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_incidents_tenant ON incidents(tenant_id);

-- 2. Habilita RLS
ALTER TABLE incidents ENABLE ROW LEVEL SECURITY;

-- 3. Policies por operación
CREATE POLICY tenant_select ON incidents
  FOR SELECT
  USING (tenant_id = current_setting('app.tenant_id', true)::uuid);

CREATE POLICY tenant_insert ON incidents
  FOR INSERT
  WITH CHECK (tenant_id = current_setting('app.tenant_id', true)::uuid);

CREATE POLICY tenant_update ON incidents
  FOR UPDATE
  USING (tenant_id = current_setting('app.tenant_id', true)::uuid)
  WITH CHECK (tenant_id = current_setting('app.tenant_id', true)::uuid);

CREATE POLICY tenant_delete ON incidents
  FOR DELETE
  USING (tenant_id = current_setting('app.tenant_id', true)::uuid);

-- 4. En la app, al inicio de cada request:
-- SET LOCAL app.tenant_id = 'uuid-del-tenant';

def execute_tool(tool_name: str, args_from_llm: dict, session: Session) -> dict:
    """Ejecuta una tool. tenant_id viene de la sesión, NO del LLM."""
    if tool_name == "search_incidents":
        # El LLM solo pasa query. tenant_id lo inyectamos NOSOTROS.
        return search_incidents(
            query=args_from_llm["query"],
            tenant_id=session.tenant_id  # ← crucial: del contexto, no del modelo
        )
    # Si el LLM intenta especificar tenant_id en args, lo ignoramos:
    if "tenant_id" in args_from_llm:
        log_security_event("LLM tried to set tenant_id", session)
        del args_from_llm["tenant_id"]

from fastapi import FastAPI
from anthropic import Anthropic
import datetime

app = FastAPI()
client = Anthropic()

TOOLS = [{
    "name": "get_current_time",
    "description": "Devuelve la hora actual UTC en ISO 8601.",
    "input_schema": {"type": "object", "properties": {}}
}]

def execute_tool(name: str, args: dict) -> str:
    if name == "get_current_time":
        return datetime.datetime.utcnow().isoformat() + "Z"
    raise ValueError(f"unknown tool {name}")

@app.get("/smoke")
def smoke_test():
    messages = [{"role": "user", "content": "¿Qué hora es?"}]
    while True:
        resp = client.messages.create(
            model="claude-haiku-4-5", max_tokens=512,
            tools=TOOLS, messages=messages
        )
        if resp.stop_reason == "tool_use":
            # Claude pidió usar una tool — ejecutamos
            tool_block = next(b for b in resp.content if b.type == "tool_use")
            result = execute_tool(tool_block.name, tool_block.input)
            messages += [
                {"role": "assistant", "content": resp.content},
                {"role": "user", "content": [{
                    "type": "tool_result",
                    "tool_use_id": tool_block.id,
                    "content": result
                }]}
            ]
            continue
        # Claude respondió final
        return {"answer": resp.content[0].text}
